def analyze(datasets):
    out = []
    trend_data = None

    # 找到包含所需列的数据集
    for ds in datasets:
        cols = ds.get('columns', [])
        if 'month' in cols and 'total_boxes' in cols and 'total_amount' in cols:
            rows = ds['rows']
            # 将行列表转换为字典列表，方便后续处理
            trend_data = []
            for row in rows:
                record = {}
                for i, col in enumerate(cols):
                    record[col] = row[i]
                trend_data.append(record)
            break

    if trend_data:
        # 转换数值类型
        for record in trend_data:
            record['total_boxes'] = float(record['total_boxes'])
            record['total_amount'] = float(record['total_amount'])

        # 按月份排序
        sorted_data = sorted(trend_data, key=lambda x: x['month'])

        if sorted_data:
            first = sorted_data[0]
            latest = sorted_data[-1]

            # 第一条记录分析
            out.append({
                'title': '最近月度采购趋势',
                'detail': '最近六个月采购箱数由 ' + str(int(first['total_boxes'])) + ' 箱变化到 ' + str(int(latest['total_boxes'])) + ' 箱，金额由 ' + str(round(first['total_amount'], 2)) + ' 变为 ' + str(round(latest['total_amount'], 2)) + '。',
                'evidence': {
                    'first_month': first['month'],
                    'first_boxes': int(first['total_boxes']),
                    'latest_month': latest['month'],
                    'latest_boxes': int(latest['total_boxes'])
                }
            })

            # 寻找峰值
            peak = max(sorted_data, key=lambda x: x['total_boxes'])

            # 高峰月分析
            out.append({
                'title': '采购高峰月',
                'detail': '采购箱数最高的月份是 ' + str(peak['month']) + '，共 ' + str(int(peak['total_boxes'])) + ' 箱，金额 ' + str(round(peak['total_amount'], 2)) + '。',
                'evidence': {
                    'peak_month': peak['month'],
                    'peak_boxes': int(peak['total_boxes'])
                }
            })

    return out
